package com.chesspulseai.entity;
import com.chesspulseai.enumtype.*; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="games",indexes=@Index(name="idx_games_status_created",columnList="status,createdAt")) public class Game { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,updatable=false,length=36) private String publicId; @Column(nullable=false,length=100) private String whitePlayer; @Column(nullable=false,length=100) private String blackPlayer; @Enumerated(EnumType.STRING) @Column(nullable=false) private PlayerColor playerColor; @Enumerated(EnumType.STRING) @Column(nullable=false) private GameStatus status=GameStatus.IN_PROGRESS; @Enumerated(EnumType.STRING) @Column(nullable=false) private GameResult result=GameResult.ONGOING; private Instant startTime; private Instant endTime; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @OneToMany(mappedBy="game",cascade=CascadeType.ALL,orphanRemoval=true) @OrderBy("moveNumber ASC") private List<ChessMove> moves=new ArrayList<>(); @PrePersist void created(){publicId=UUID.randomUUID().toString();createdAt=updatedAt=Instant.now();startTime=createdAt;} @PreUpdate void updated(){updatedAt=Instant.now();} public Long getId(){return id;} public String getPublicId(){return publicId;} public String getWhitePlayer(){return whitePlayer;} public void setWhitePlayer(String v){whitePlayer=v;} public String getBlackPlayer(){return blackPlayer;} public void setBlackPlayer(String v){blackPlayer=v;} public PlayerColor getPlayerColor(){return playerColor;} public void setPlayerColor(PlayerColor v){playerColor=v;} public GameStatus getStatus(){return status;} public void setStatus(GameStatus v){status=v;} public GameResult getResult(){return result;} public void setResult(GameResult v){result=v;} public Instant getStartTime(){return startTime;} public Instant getEndTime(){return endTime;} public void setEndTime(Instant v){endTime=v;} public Instant getCreatedAt(){return createdAt;} public List<ChessMove> getMoves(){return moves;} }
